import React from "react";
import styled from "styled-components";
import { device } from "../../helpers/MediaQ";

const BuilderBrand = styled.div`
  margin-bottom: ${(p) => (p.last ? "0" : "2rem")};
  grid-column-gap: 2rem;
  display: grid;
  grid-template-columns: auto 1fr;

  h4 {
    padding-bottom: 1rem;
    grid-column-start: 1;
    grid-column-end: 3;
  }

  @media ${device.sm} {
    display: block;
  }
`;

export const Builder_Brand = (props) => {
  return (
    <BuilderBrand
      className={props.className + " " + "BuilderBrand"}
      last={props.last}
      key={props.key}
    >
      {props.title ? <h4>{props.title}</h4> : null}
      {props.children}
    </BuilderBrand>
  );
};
