import React from 'react'
import styled from 'styled-components'
import { Input_ } from './Input_'

const BackendSearch = styled.div``

const BackendSearchSuggestions = styled.div``

const BackendSearchList = styled.div``

export const Backend_Search = (props) => {
  return (
    <BackendSearch>
        <Input_
            id="backendSearch"
            placeholder={props.placeholder}
            autoComplete="off"
            type={props.type || "text"}
            value={props.value}
            onChange={props.onChange}
            onKeyPress={props.onKeyPress}
        />
        <BackendSearchSuggestions className="backendSearchSuggestions">
            {data.searchResults?.map((suggestion, i) => (
                <li
                className={
                    i === (highlighted % data.searchResults?.length) - 1
                    ? "ElasticSelected"
                    : ""
                }
                key={i}
                onClick={() => handleSelection(suggestion)}
                >
                <p>{suggestion[props.displayProperty]}</p>
                </li>
            ))}
        </BackendSearchSuggestions>
        {props.list ? (
            <BackendSearchList className="backendSearchList">
                <h5>{props.selectionSectionTitle}</h5>
                {data.selected?.map((item, i) => (
                    <li key={i}>
                        {props.selectionItemIcon && (
                            <IconSvg Icon={props.selectionItemIcon} />
                        )}
                        <h6>{item[props.displayProperty]}</h6>
                        <Red_
                            size="small"
                            iconLeft="Delete"
                            onClick={() => handleDeletion(i)}
                        />
                    </li>
                ))}
            </BackendSearchList>) 
        : 
            null
        }
    </BackendSearch>
  )
}
