import React from "react";
import styled, { keyframes } from "styled-components";

const Line = keyframes`
    0%{
      opacity: 1;
      transform: translateX(-110%);
      background: var(--main);
    }

    25%{
      opacity: 0.3;
      background: var(--focus);
    }

    50%{
      opacity: 1;
      background: var(--main);
      transform: translateX(+110%);
    }

    75%{
      opacity: 0.3;
      background: var(--focus);
    }

    100%{
      opacity: 1;
      transform: translateX(-110%);
      background: var(--main);
    }
`;

const MainLoader = styled.div`
  position: fixed;
  top: 6rem;
  left: 0;
  height: calc(100vh - 6rem);
  width: 100%;
  background: ${(p) => p.theme.low};
  z-index: 10000;

  main {
    height: 2px;
    width: 100%;
    position: fixed;
    top: 6rem;
    left: 0;
    animation: ${Line} 3s infinite;
    animation-timing-function: linear;
  }
`;

export const Main_Loader = (props) => {
  return (
    <MainLoader>
      <main></main>
    </MainLoader>
  );
};
