import React from "react";
import styled from "styled-components";
import Upload_ from "./Upload_";

const UploadLogo = styled.div`
  display: grid;
  grid-template-columns: auto 1fr;
  grid-gap: 2rem;
`;

const UploadLogoImage = styled.div`
  width: 5.8rem;
  aspect-ratio: 1/1;
  background: ${(p) => p.theme.bg};
  border-radius: 0.2rem;
  overflow: hidden;

  img {
    height: 100%;
    width: 100%;
    object-fit: cover;
  }
`;

const UploadLogoActions = styled.div`
  display: flex;
`;

export const Upload_Logo = (props) => {
  return (
    <UploadLogo>
      <UploadLogoImage>
        {props.img && props.uploaded ? (
          <img src={props.img} />
        ) : (
          <img
            src={
              props.imgDefault
                ? props.imgDefault
                : "https://genius1071.friktoriaservers.net/doitforme/morning/app/boiler/DefaultAvatar.jpg"
            }
          />
        )}
      </UploadLogoImage>
      <UploadLogoActions>
        <Upload_
          maxFiles="1"
          getFilesFromChild={props.getFilesFromChild}
          boomRejected={props.boomRejected}
          accept={props.accept}
          onClick={props.onUpload}
          text={props.upload}
          iconLeft={props.iconUpload ? props.iconUpload : "Upload"}
          maxSize={props.maxSize}
          userId={props.userId}
        />
      </UploadLogoActions>
    </UploadLogo>
  );
};
