import React from "react";
import styled, { keyframes } from "styled-components";

const Line = keyframes`
    0%{
      opacity: 1;
      transform: translateX(-110%);
      background: var(--main);
    }

    25%{
      opacity: 0.3;
      background: var(--focus);
    }

    50%{
      opacity: 1;
      background: var(--main);
      transform: translateX(+110%);
    }

    75%{
      opacity: 0.3;
      background: var(--focus);
    }

    100%{
      opacity: 1;
      transform: translateX(-110%);
      background: var(--main);
    }
`;

const PartialLoader = styled.div`
    height: 100%;
    width: 100%;
    overflow: hidden;

  main {
    height: 2px;
    width: 100%;
    animation: ${Line} 3s infinite;
    animation-timing-function: linear;
  }
`;

export const Partial_Loader = (props) => {
  return (
    <PartialLoader>
        <main></main>
    </PartialLoader>
  )
}
