import styled, { keyframes } from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import React, { useContext, useEffect, useRef, useState } from "react";
import { AlertContext } from "../../contexts";

export const FadeIn = keyframes`
    0% { 
      transform: translate(-100%);
    }

    10%{
      transform: translate(-20%);
    }

    90%{
      transform: translate(0%);
    }
`;

const Rotate = keyframes`
    0% { 
        opacity: 0;
        transform: rotate(0deg);
    }

    10%{
      opacity: 1;
    }

    90%{
      opacity: 1;
    }

    100% { 
        opacity: 0;
        transform: rotate(360deg);
    }
`;

export const Alert = styled.ul`
  position: fixed;
  max-height: 11.5rem;
  overflow: hidden;
  top: 7rem;
  left: 1rem;
  z-index: 2000;
  display: flex;
  flex-direction: column-reverse;
  justify-content: flex-end;
  gap: 1rem;
`;

export const AlertSingle = styled.li`
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: flex-start;
  grid-gap: 1rem;
  padding: 0.5rem 1rem;
  border-radius: 1rem;
  max-width: calc(100vw - 2rem);
  animation: ${FadeIn} 1s linear;
  background: ${(p) =>
    p.status === "Error"
      ? "var(--error)"
      : p.status === "Loading"
      ? "var(--warning)"
      : "var(--success)"};

  .Loading {
    animation: ${Rotate} infinite 2s linear;
  }
`;

export const AlertContainer = styled.div`
  display: flex;
  align-items: center;

  h6 {
    color: var(--white) !important;
  }
`;

export const AlertIcon = styled.div`
  width: 1.6rem;

  svg {
    fill: var(--white);
    width: 100%;
  }
`;
export const Alert_ = (props) => {
  const { alerts, setAlerts } = useContext(AlertContext);
  const timeouts = useRef([]); // Reference to store all timeouts

  const alertDuration = (id) => {
    let duration = props.duration ? props.duration : 2000;

    const timeoutId = setTimeout(() => {
      setAlerts((oldAlerts) => oldAlerts.filter((alert) => alert.id !== id));
    }, duration);
    timeouts.current.push(timeoutId); // Push this timeout to the array
  };

  useEffect(() => {
    alerts.forEach((alert) => {
      alertDuration(alert.id);
    });

    return () => {
      // On unmount or when alerts change, clear all timeouts
      timeouts.current.forEach((timeout) => clearTimeout(timeout));
      timeouts.current = [];
    };
  }, [alerts]);

  return (
    <Alert storybook={props.storybook} className={props.className + ' ' + 'Alert'} >
      {alerts?.map((item, i) => (
        <AlertSingle status={item.message.status} key={i}>
          <AlertIcon>
            <IconSvg
              // class_Icon={item.message.status === "Loading" ? "Loading" : ""}
              Icon={
                item.message.status === "Error" ? "Xicon" : "Check"
              }
            />
          </AlertIcon>
          <AlertContainer>
            <h6>{item.message.text}</h6>
          </AlertContainer>
        </AlertSingle>
      ))}
      {props.loadingStatus ?
        <AlertSingle status="Loading">
          <AlertIcon>
            <IconSvg
              class_Icon="Loading"
              Icon="Loading"
            />
          </AlertIcon>
          <AlertContainer>
            <h6>{props.loadingText}</h6>
          </AlertContainer>
        </AlertSingle>
      :
        null
      }
    </Alert>
  );
};
