import React from "react";
import styled from "styled-components";
import { Card } from "../../helpers/Card";
import { Main_Plain } from "../button";
import { Toggle_ } from "../form/Toggle_";

const OnGradientCard = styled(Card)`
  cursor: ${p => p.onClick ? 'pointer' : 'default'};;
  box-shadow: ${(p) => p.theme.out};

  &:hover {
    box-shadow: ${p => p.onClick ? p.theme.outFocus : 'none'};
  }
`;

const OnGradientCardTop = styled.div`
  height: 15rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(
    to bottom right,
    ${(p) => p.firstColor},
    ${(p) => p.secondColor}
  );
`;

const OnGradientCardImg = styled.img`
  height: 8rem;
`;
const OnGradientCardContent = styled.div`
  background: ${(p) => p.theme.background};
  padding: 2rem;
  border-radius: 1.5rem;
  transform: translateY(-2rem);
  height: calc(100% - 13rem);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
`;

const OnGradientCardDesc = styled.div`
  h3 {
    margin-bottom: 2rem;
  }
`;

const OnGradientCardActions = styled.div`
  display: flex;
  align-items: center;
  justify-content: flex-end;
  margin-top: 1rem;
`;

export const On_Gradient_Card = (props) => {
  return (
    <OnGradientCard className={props.className} onClick={props.onClick} id={props.id} key={props.key}>
      <OnGradientCardTop
        firstColor={props.firstColor}
        secondColor={props.secondColor}
      >
        <OnGradientCardImg src={props.img} />
      </OnGradientCardTop>
      <OnGradientCardContent>
        <OnGradientCardDesc>
          <h3>{props.title}</h3>
          <p>{props.text}</p>
        </OnGradientCardDesc>
        {props.textBtn || props.toggle?
        <>
          {props.textBtn ?
            <OnGradientCardActions>
              <Main_Plain text={props.textBtn} iconLeft={props.iconBtn} noPadding />
            </OnGradientCardActions>
          :
            <OnGradientCardActions>
              <Toggle_ active={props.active} />
            </OnGradientCardActions>
          }
        </>
        :
          <>{props.children}</>
        }
      </OnGradientCardContent>
    </OnGradientCard>
  );
};
