import React from "react";
import styled from "styled-components";
import { Label, Textarea } from "../../helpers/Input";
import {
  ValidatorError,
  ValidatorRequired,
  Validators,
  ValidatorSuccess,
  ValidatorTip,
  ValidatorWarning,
} from "../../helpers/Validator";
import { IconSvg } from "../../svg/IconSvg";
import { FormGroup } from "../../styles/Form";

const TextAreaGroup = styled(FormGroup)`
  position: relative;

  textarea:placeholder-shown {
    ~ label {
      transform: translateY(0rem);
      visibility: hidden;
      opacity: 0;
    }

    ~ .ValidatorHelpers {
      display: none;
    }

    ~ .ValidatorErrors {
      display: block;
    }

    ~ .FormAddButton {
      display: none;
    }
  }
`;

const TextAreaLabel = styled(Label)`
  font-size: var(--smallText);
  color: var(--greyDark);
`;

const TextAreaCounter = styled.h6`
  text-align: right;

  span {
    color: ${(p) => (p.capped ? "var(--error)" : "inherit")};
  }
`;

export const Textarea_ = (props) => {
  return (
    <TextAreaGroup>
      <Textarea
        ref={props.ref}
        className={props.className}
        placeholder={props.placeholder}
        rows={props.rows ? props.rows : "5"}
        onChange={props.onChange}
        maxLength={props.limit}
        value = {props.value}
        defaultValue={props.defaultValue}
        onKeyDown={props.onKeyDown}
        onBlur={props.onBlur}
      >
        {props.inTextarea}
      </Textarea>
      <TextAreaLabel>{props.placeholder}</TextAreaLabel>
      {props.limit && props.valueLength ? (
        <TextAreaCounter capped={props.count > props.limit ? true : false}>
          <span>{props.valueLength}</span> / {props.limit}
        </TextAreaCounter>
      ) 
      :props.valueLength ? (
        <TextAreaCounter>
          <span>{props.valueLength}</span>
        </TextAreaCounter>
      ) :
        null
      }
      {props.required ? (
        <ValidatorRequired className="ValidatorRequired">
          <IconSvg Icon="Asterisk" />
        </ValidatorRequired>
      ) : null}
      {props.errors ? (
        <Validators className="ValidatorErrors">
          {props.errors?.map((error) => (
            <ValidatorError>
              <IconSvg Icon="Error" />
              <h6>{error}</h6>
            </ValidatorError>
          ))}
        </Validators>
      ) : null}
      {props.successes ? (
        <Validators className="ValidatorSuccesses">
          {props.successes?.map((success, i) => (
            <ValidatorSuccess key={i}>
              <IconSvg Icon="Check" />
              <h6>{success}</h6>
            </ValidatorSuccess>
          ))}
        </Validators>
      ) : null}
      {props.tips && props.helpers ? (
        <Validators className="ValidatorHelpers">
          {props.helpers?.map((helper) => (
            <ValidatorWarning>
              <IconSvg Icon="Warning" />
              <h6>{helper}</h6>
            </ValidatorWarning>
          ))}
          {props.tips?.map((tip) => (
            <ValidatorTip>
              <IconSvg Icon="Tip" />
              <h6>{tip}</h6>
            </ValidatorTip>
          ))}
        </Validators>
      ) : props.tips ? (
        <Validators className="ValidatorHelpers">
          {props.tips?.map((tip) => (
            <ValidatorTip>
              <IconSvg Icon="Tip" />
              <h6>{tip}</h6>
            </ValidatorTip>
          ))}
        </Validators>
      ) : props.helpers ? (
        <Validators className="ValidatorHelpers">
          {props.helpers?.map((helper) => (
            <ValidatorWarning>
              <IconSvg Icon="Warning" />
              <h6>{helper}</h6>
            </ValidatorWarning>
          ))}
        </Validators>
      ) : null}
    </TextAreaGroup>
  );
};
