import React from 'react'
import styled from 'styled-components'

const UploadBar = styled.div`
  position: fixed;
  top: 0;
  left: 0;
  height: 100vh;
  width: 100vw;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 20;
  background: rgba(8, 18, 38, .38);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
`

const UploadBarWrapper = styled.div`
  width: 100%;
  max-width: 40rem;
  background: ${p => p.theme.low};
  border: 1px solid ${p => p.theme.high};
  padding: var(--largePads);
  border-radius: var(--smallRadius);
`

const UploadBarHeader = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: .8rem;
`

const UploadBarTrack = styled.div`
  width: 100%;
  height: 1rem;
  border-radius: 999px;
  overflow: hidden;
  background: ${p => p.theme.mid};
  border: 1px solid ${p => p.theme.high};
`

const UploadBarFill = styled.div`
  width: ${({ $percentage }) => `${$percentage}%`};
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--main), var(--mainDark));
  transition: width .2s ease;
`

const clampPercentage = (value) => {
  const parsed = Number(value)
  if (!Number.isFinite(parsed)) return 0
  return Math.max(0, Math.min(100, Math.round(parsed)))
}

export const Upload_Bar = (props) => {
  const percentage = clampPercentage(props?.ulpoadPercentage ?? props?.uploadedPercentage)
  const text = props?.text || 'Uploading media...'

  return (
    <UploadBar>
        <UploadBarWrapper>
            <UploadBarHeader>
                <h4>{text}</h4>
                <h4>{percentage}%</h4>
            </UploadBarHeader>
            <UploadBarTrack
                role="progressbar"
                aria-valuemin={0}
                aria-valuemax={100}
                aria-valuenow={percentage}
            >
                <UploadBarFill $percentage={percentage} />
            </UploadBarTrack>
        </UploadBarWrapper>
    </UploadBar>
  )
}