import React from "react";
import styled from "styled-components";

const ColorPicker = styled.div`
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  grid-gap: 1rem;

  input {
    padding: 0;
    margin: 0;
    height: 4rem;
    width: 8rem;
    cursor: pointer;
    border: none;
    outline: 0;
  }
`;

export const Color_Picker = (props) => {
  const change_color = (event) => {
    const newColor = event.target.value;
    props.passColor({ colorType: props.colorType, newColor });
  };

  return (
    <ColorPicker
      id={props.id}
      className={props.className + "ColorPicker"}
      key={props.key}
    >
      <input
        type="color"
        value={props.selectedColor}
        onChange={(event) => change_color(event)}
      />
      <h5>{props.text}</h5>
    </ColorPicker>
  );
};
