import React from "react";
import { Toggle, ToggleBtn } from "../../helpers/Toggle";

export const Toggle_ = (props) => {
  return (
    <Toggle
      className={props.className + " " + "Toggle"}
      id={props.id}
      onClick={props.onToggle}
    >
      <ToggleBtn className={props.active ? "Right" : "Left"}></ToggleBtn>
    </Toggle>
  );
};
