import React, { useState } from 'react'
import styled from 'styled-components';
import { Actions_, Main_Plain, Red_ } from '../button';
import { Slider_ } from '../slider';
import { Builder_, Input_ } from '../form';

const Timeline = styled.div`
  
`;

const TimelineGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  grid-template-rows: 3rem 3rem 3rem;
`

const TimelineBox = styled.div`
  height: 100%;
  width: 100%;
  background: ${p => p.status === 'success' ? 'var(--success)' : 'var(--error)'};
  border-bottom: 1px solid ${p => p.theme.background};
  grid-column: span ${p => p.continuity};
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform .5s;
  /* position: relative; */

  h5{
    color: var(--white);
  }

  &:hover{
    transition: transform .5s;
    transform: scale(.95);
  }
`

const TimelineBoxComment = styled.div`
  position: absolute;
  top: 1rem;
  left: 1rem;
  min-width: 35rem;
`

export const Timeline_ = (props) => {

    const [slider, setSlider] = useState({ status: false, key: null });
    const [inputValue, setInputValue] = useState('');

    const [fields, setFields] = useState([
        {
          status: 'success',
          continuity: 1,
          note: ''
        },
      ]);
  
    const handleSliderClick = (index) => {
      const selectedField = fields[index];
    setSlider(prevSlider => ({
      status: true,
      key: prevSlider.key === index ? null : index
    }));
    setInputValue(selectedField.note);
    };

    const closeSlider = () => {
      setFields(prevFields =>
        prevFields.map((field, index) =>
          index === slider.key ? { ...field, note: inputValue } : field
        )
      );
      setSlider({ status: false, key: null });
    };

  const addFieldWithSuccess = () => {
    setFields(prevFields => {
      const lastField = prevFields[prevFields.length - 1];
      if (lastField.status === 'success') {
        return prevFields.map((field, index) => 
          index === prevFields.length - 1 
            ? { ...field, continuity: field.continuity + 1 } 
            : field
        );
      } else {
        return [...prevFields, { status: 'success', continuity: 1 }];
      }
    });
  };

  const addFieldWithError = () => {
    setFields(prevFields => {
      const lastField = prevFields[prevFields.length - 1];
      if (lastField.status === 'error') {
        return prevFields.map((field, index) => 
          index === prevFields.length - 1 
            ? { ...field, continuity: field.continuity + 1 } 
            : field
        );
      } else {
        return [...prevFields, { status: 'error', continuity: 1 }];
      }
    });
  };

  return (
    <Timeline>
      {slider.status && slider.key !== null && (
        <Slider_ done="Done" onClick={closeSlider} noClose={closeSlider}>
          <Builder_ text="Leave a comment">
            <Input_
              placeholder="Comment"
              defaultValue={fields[slider.key].note}
              onChange={e => setInputValue(e.target.value)}
            />
          </Builder_>
        </Slider_>
      )}
      <Actions_>
        <Main_Plain size="small" text="success" onClick={addFieldWithSuccess} />
        <Red_ size="small" text="Error" onClick={addFieldWithError} />
      </Actions_>
      <TimelineGrid>
        {fields.map((field, i) => (
          <TimelineBox key={i} continuity={field.continuity} status={field.status} onClick={() => handleSliderClick(i)}>
            <h5>{field.note}</h5>
          </TimelineBox>
        ))}
      </TimelineGrid>
    </Timeline>
  )
}
