import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const Main = styled(Button)`
  background: var(--main);
  border-radius: var(--normalRadius);
  border: 1px solid var(--main);

  span {
    color: var(--white);
  }

  svg {
    fill: var(--white);
  }

  &:hover {
    background: var(--mainLight);
    border: 1px solid var(--mainLight);
  }
`;

export const Main_ = (props) => {
  return (
    <Main
      className={props.className + " " + "Main"}
      id={props.id}
      size={props.size}
      onClick={props.onClick}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </Main>
  );
};
