import styled from "styled-components";

export const Button = styled.button`
  display: flex;
  align-items: center;
  gap: 1rem;
  outline: 0;
  border: none;
  cursor: pointer;
  transition-property: background, border;
  transition-duration: 0.5s;
  padding: ${(p) =>
    p.noPadding === true
      ? "0 !important"
      : p.size === "small"
      ? "var(--smallPads)"
      : p.size === "large"
      ? "var(--largePads)"
      : "var(--normalPads)"};

  svg {
    transition-property: fill;
    transition-duration: 0.5s;
    width: ${(p) =>
      p.size === "small"
        ? "var(--smallIcon)"
        : p.size === "large"
        ? "var(--largeIcon)"
        : "var(--normalIcon)"};
  }

  img {
    width: ${(p) =>
      p.size === "small"
        ? "var(--smallIcon)"
        : p.size === "large"
        ? "var(--largeIcon)"
        : "var(--normalIcon)"};
  }

  span {
    white-space: nowrap;
    transition-property: color;
    transition-duration: 0.5s;
    font-size: ${(p) =>
      p.size === "small"
        ? "var(--smallText)"
        : p.size === "large"
        ? "var(--largeText)"
        : "var(--normalText)"};
  }

  &:active {
    transform: scale(0.97);
  }
`;
