import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const GreyLink = styled(Button)`
  background: transparent;
  border: 1px solid transparent;

  span {
    color: var(--greyDark);
    text-decoration: underline;
  }

  svg {
    fill: var(--greyDark);
  }

  &:hover {
    span {
      color: ${(props) => props.theme.color};
    }

    svg {
      fill: ${(props) => props.theme.color};
    }
  }
`;

export const Grey_Link = (props) => {
  return (
    <GreyLink
      className={props.className + " " + "GreyLink"}
      id={props.id}
      size={props.size}
      onClick={props.onClick}
      noPadding={props.noPadding}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </GreyLink>
  );
};
