import React from "react";
import styled from "styled-components";
import { Main_Plain } from "../button";

const OnStat = styled.div`
  width: 100%;
  background: ${(props) => props.theme.background};
  color: ${(props) => props.theme.color};
  box-shadow: ${(p) => p.theme.out};
  border-radius: var(--smallRadius);
  transition: box-shadow 0.5s;
  overflow: hidden;
  padding: var(--largePads);
  cursor: pointer;

  &:hover {
    transition: box-shadow 0.5s;
    box-shadow: ${(p) => p.theme.outFocus};
  }
`;

const OnStatTop = styled.div``;

const OnStatText = styled.h1`
  color: ${(p) =>
    p.variant == "focus"
      ? "var(--focus)"
      : p.variant == "main"
      ? "var(--main)"
      : "inherit"} !important;
`;

const OnStatTitle = styled.h6``;

const OnStatBottom = styled.div`
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 1rem;
`;

const OnStatEdited = styled.h6`
  color: ${(p) => p.theme.high};
`;

export const On_Stat = (props) => {
  return (
    <OnStat className={props.className + ' ' + 'OnStat'} id={props.id} onClick={props.onClick}>
      <OnStatTop className='OnStatTop'>
        <OnStatTitle>{props.title}</OnStatTitle>
        <OnStatText variant={props.variant}>{props.text}</OnStatText>
      </OnStatTop>
      <OnStatBottom className='OnStatBottom'>
        <OnStatEdited>{props.edited}</OnStatEdited>
        <Main_Plain iconLeft={props.btnIcon} text={props.btnText} noPadding />
      </OnStatBottom>
    </OnStat>
  );
};
