import React from "react";
import styled, { keyframes } from "styled-components";

const MLPurpleLight = keyframes`
    0%{transform: rotate(0deg);}
    25%{transform: rotate(90deg)}
    50%{transform: rotate(180deg)}
    75%{transform: rotate(270deg)}
    100%{transform: rotate(360deg);}
`;

const MLTurqLight = keyframes`
    0%{transform: rotate(0deg);}
    25%{transform: rotate(-90deg)}
    50%{transform: rotate(-180deg)}
    75%{transform: rotate(-270deg)}
    100%{transform: rotate(-360deg);}
`;

const MLPurple = keyframes`
    0%{transform: translate(0, 0)}
    50%{transform: translate(-.1rem, -.1rem)}
    100%{transform: translate(0, 0)}
`;

const MLTurq = keyframes`
    0%{transform: translate(0, 0)}
    50%{transform: translate(.1rem, .1rem)}
    100%{transform: translate(0, 0)}
    `;

const Text = keyframes`
0%{opacity: 1}
50%{opacity: .3}
100%{opacity: 1}
`;

const PartialTextLoader = styled.div`
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
  background: ${(p) => p.theme.low};
  z-index: 10000;

  main {
    position: absolute;
    top: 2rem;
    left: 2rem;
    height: 3rem;
  }
`;

const PartialTextLoaderText = styled.div`
  position: absolute;
  top: 2.5rem;
  left: 6rem;
  width: calc(100vw - 7rem);
  animation: ${Text} 3s infinite;
  animation-timing-function: linear;
`;

const PurpleLight = styled.img`
  height: 100%;
  width: 100%;
  animation: ${MLPurpleLight} 3s infinite;
  animation-timing-function: linear;
`;

const TurqLight = styled.img`
  height: 100%;
  width: 100%;
  animation: ${MLTurqLight} 3s infinite;
  animation-timing-function: linear;
`;

const TurqLogo = styled.img`
  height: 100%;
  width: 100%;
  animation: ${MLTurq} 4s infinite;
  animation-timing-function: linear;
`;

const PurpleLogo = styled.img`
  height: 100%;
  width: 100%;
  animation: ${MLPurple} 4s infinite;
  animation-timing-function: linear;
`;

export const Partial_Text_Loader = (props) => {
  return (
    <PartialTextLoader>
      <main>
        <PurpleLight
          src="https://genius1071.friktoriaservers.net/mongol/app/illus/mainLoader/pLight.svg"
          alt=""
        />
      </main>
      <main>
        <TurqLight
          src="https://genius1071.friktoriaservers.net/mongol/app/illus/mainLoader/tLight.svg"
          alt=""
        />
      </main>
      <main>
        <TurqLogo
          src="https://genius1071.friktoriaservers.net/mongol/app/illus/mainLoader/turq.svg"
          alt=""
        />
      </main>
      <main>
        <PurpleLogo
          src="https://genius1071.friktoriaservers.net/mongol/app/illus/mainLoader/purple.svg"
          alt=""
        />
      </main>
      <PartialTextLoaderText>
        <h6>{props.text}</h6>
      </PartialTextLoaderText>
    </PartialTextLoader>
  );
};
