import React, { useContext, useEffect, useRef } from "react";
import styled from "styled-components";
import { HamContext, MenuContext } from "../../contexts/NavbarContext";
import { device } from "../../helpers/MediaQ";
import { Grey_ } from "../button";
import { Nav_Ham } from "./Nav_Ham";
import { Nav_Home } from "./Nav_Home";
import { NavAll } from "../../styles/Ham";
import { logo } from "../../styles/Theme";
import { ThemeContext } from "../../contexts";
import { Nav_All_Ham } from "./Nav_All_Ham";

const NavProtected = styled.div`
  justify-self: flex-end;
  display: flex;
  align-items: center;
  gap: 1rem;
  position: relative;

  padding: 1rem 4rem 1rem 1rem;

  @media ${device.sm} {
    padding-right: 2rem;
  }
`;

const NavUser = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  cursor: pointer;
  background: ${(p) => p.theme.mid};
  border: 1px solid ${(p) => p.theme.mid};
  border-radius: 2rem;
  padding: 0.1rem 2rem 0.1rem 0.1rem;
  transition-property: background, border;
  transition-duration: 0.5s;

  picture {
    height: 3rem;
    width: 3rem;
    border-radius: 50%;
    overflow: hidden;
    border: 1px solid ${(p) => p.theme.background};

    img {
      height: 100%;
      width: 100%;
      object-fit: cover;
    }
  }

  &:hover {
    background: ${(p) => p.theme.low};
    border: 1px solid ${(p) => p.theme.low};
  }

  /* @media ${device.sm} {
    padding: 0;

    h5 {
      display: none;
    }
  } */
`;

const NavProtectedNotifications = styled.div`
  position: relative;
  cursor: pointer;
`

const NavProtectedNotificationsNumber = styled.div`
  position: absolute;
  top: -.5rem;
  right: -.5rem;
  background: var(--error);
  padding: 3px 5px;
  border-radius: 5px;


  h4{
    font-size: 1.2rem;
    color: var(--white);
  }
`

export const Nav_Protected = (props) => {
  const {theme} = useContext(ThemeContext);
  const { hamState, setHamState } = useContext(HamContext);
  const { setActiveMenu } = useContext(MenuContext);

  const hamMenu = useRef();

  const clickOutside = (event) => {
    if (hamMenu.current && !hamMenu.current.contains(event.target)) {
      setHamState(false);
      setActiveMenu("Main");
    }
  };

  useEffect(() => {
    // Attach the listeners on component mount.
    document.addEventListener("mousedown", clickOutside);
    // Detach the listeners on component unmount.
    return () => {
      document.removeEventListener("mousedown", clickOutside);
    };
  }, []); // Empty array ensures that effect is only run on mount and unmount

  return (
    <NavProtected ref={hamMenu}>
      <NavUser onClick={props.onClick_Account}>
        <picture>
          <img
            src={props.img_Account}
            alt={props.imgAlt_Account}
            onError={props.imgError_Account}
          />
        </picture>
        <h5>{props.firstname_Account}</h5>
      </NavUser>
      <NavProtectedNotifications onClick={props.onClick_Notifications}>
        <Grey_
          className="Notifications"
          iconLeft="Notifications"
          onClick={props.onClick_Notifications}
        />
        {props.unread_Notifications?.length > 0 ? 
          <NavProtectedNotificationsNumber>
            <h4>{props.unread_Notifications}</h4>
          </NavProtectedNotificationsNumber>
        :
          null
        }
      </NavProtectedNotifications>
      <Grey_
        className="Ham"
        iconLeft="Ham"
        onClick={() => setHamState('menu')}
      />
      {hamState === 'menu' ? 
        <Nav_Ham
          hamExtraItems={props.hamExtraItems}
          role={props.role}
          text_Admin_Main={props.text_Admin_Main}
          onClick_Admin_Main={props.onClick_Admin_Main}
          idAdminMain={props.idAdminMain}
          onClick_Title_Main={props.onClick_Title_Main}
          text_Subscriptions_Main={props.text_Subscriptions_Main}
          onClick_Subscriptions_Main={props.onClick_Subscriptions_Main}
          idSubscriptionsMain={props.idSubscriptionsMain}
          text_Title_Main={props.text_Title_Main}
          text_Theme_Main={props.text_Theme_Main}
          onCLick_Account_Main={props.onCLick_Account_Main}
          idAccountMain={props.idAccountMain}
          img_Account_Main={props.img_Account_Main}
          imgAlt_Account_Main={props.imgAlt_Account_Main}
          text_Account_Main={props.text_Account_Main}
          onClick_Settings_Main={props.onClick_Settings_Main}
          idSettingsMain={props.idSettingsMain} 
          text_Settings_Main={props.text_Settings_Main}
          onClick_Logout={props.onClick_Logout}
          idLogout={props.idLogout}
          text_Logout={props.text_Logout}
          text_Title_Region={props.text_Title_Region}
          text_Title_Language={props.text_Title_Language}
          onClick_Greek_Language={props.onClick_Greek_Language}
          onClick_English_Language={props.onClick_English_Language}
          onClick_German_Language={props.onClick_German_Language}
        />
      : 
        null
      }
    </NavProtected>
  );
};
