import React from "react";
import styled from "styled-components";
import { device } from "../../helpers/MediaQ";
import { Grey_, Main_ } from "../button";

const Slider = styled.div`
  position: ${(p) => (p.storybook ? "static" : "fixed")};
  top: 0;
  left: 0;
  z-index: 500;
  width: 100%;
  height: 100vh;

  .Main{
    pointer-events: ${p => p.disabled ? 'none' : 'all'} !important;
    opacity: ${p => p.disabled ? '0.5' : '1'} !important; //Alert option remove this part in Future in order to work
    cursor: ${p => p.disabled ? 'not-allowed' : 'pointer'} !important;
    transition: al .5s ease-in-out;
  }
`;

const SliderOverlay = styled(Slider)`
  position: ${(p) => (p.storybook ? "static" : "fixed")};
  top: 0;
  right: 0;
  z-index: 501;
  width: 100%;
  height: 100%;
  background: ${(p) => p.theme.overlay};
`;

const SliderWrapper = styled.div`
  position: ${(p) => (p.storybook ? "static" : "fixed")};
  top: 0;
  right: 0;
  z-index: 502;
  width: 100%;
  height: 100%;
  max-width: 60%;
  background-color: ${(p) => p.theme.background};

  @media ${device.md} {
    max-width: 100%;
  }
`;

const SliderTitle = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 6rem;
  padding: 0 4rem;

  @media ${device.sm} {
    button {
      span {
        /* display: none !important; */
      }
    }
  }

  @media ${device.xs} {
    h3 {
      display: ${(p) => (p.grey ? "none" : "block")};
    }
  }
`;

const SliderContainer = styled.div`
  padding: 2rem 4rem 10rem 4rem;
  background: ${(p) => p.theme.low};
  height: 100%;
  overflow: auto;
`;

export const Slider_ = (props) => {
  return (
    <Slider
      className={props.className + " " + "Slider"}
      disabled={props.disabled}
    >
      <SliderOverlay
        onClick={props.onClose}
      ></SliderOverlay>
      <SliderWrapper className="SliderWrapper">
        <SliderTitle grey={props.grey} className="SliderTitle">
          {props.iconGreyRight || props.iconGreyLeft ? (
            <Grey_
              id={props.idGrey}
              text={props.grey}
              iconRight={props.iconGreyRight ? props.iconGreyRight : null}
              iconLeft={props.iconGreyLeft ? props.iconGreyLeft : null}
              size="normal"
              onClick={props.onGrey}
            />
          ) : null}
          <h3>{props.title}</h3>
          {props.onClick ? (
            <Main_
              id={props.id}
              text={props.text}
              iconRight={props.icon ? props.icon : "Check"}
              size="normal"
              onClick={props.onClick}
            />
            ) : null
          }
        </SliderTitle>
        <SliderContainer className="SliderContainer">
          {props.children}
        </SliderContainer>
      </SliderWrapper>
    </Slider>
  );
};
