import { useDropzone } from "react-dropzone";
import React, { useCallback, useEffect, useState } from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const Upload = styled(Button)`
  background: transparent;
  border: 1px solid transparent;

  span {
    color: var(--main);
  }

  svg {
    fill: var(--main);
  }

  &:hover {
    span {
      color: var(--mainLight);
    }

    svg {
      fill: var(--mainLight);
    }
  }
`;

export default function Upload_(props) {
  const [files, setFiles] = useState(props.files);

  const boomRejected = (type, filename) => {
    props.boomRejected(type, filename);
  };

  const {
    getRootProps,
    getInputProps,
    isDragActive,
    isDragAccept,
    isDragReject,
  } = useDropzone({
    accept: props.accept
      ? props.accept
      : "image/svg, image/jpeg, image/png, image/jpg, video/mp4, video/mpeg, video/webm",
    onDrop: useCallback((acceptedFiles) => {
      const files = acceptedFiles.map((file) => {
        // Extract file extension
        const fileExtension = file.name.split('.').pop();
        // Rename file using userId and file extension
        
        const newName =props.userId ? `${props.userId}.${fileExtension}` : file.name;

        let preview = URL.createObjectURL(file);

        let newFile = new File([file], newName, { type: file?.type})
        
        newFile.preview = preview;

        return newFile;
     
      });


    console.log('FILES', files);

      let tempFiles = [];
      files.forEach((file) => {
        if (props.type === "video" && file.size > props.maxSize) {
          boomRejected("videoSize", file.name);
        } else if (
          props.accept &&
          props.accept !== "" &&
          !props.accept.split(',').map(type => type.trim()).includes(file.type)
        ) {
          boomRejected("fileMimetype", file.name);
        }
         else if (
          file?.type !== "image/png" &&
          file?.type !== "image/jpeg" &&
          file?.type !== "video/mp4" &&
          file?.type !== "video/mpeg" &&
          file?.type !== "image/webm"
        ) {
          boomRejected("fileMimetype", file.name);
        } 
        else if (file.size > props.maxSize) {
          boomRejected("fileSize", file.name);
        } else {
          tempFiles.push(file);
        }
      });

      if (tempFiles?.length > 0) {
        setFiles(tempFiles);
      }
    }, [props.userId, props.accept, props.maxSize, props.type, boomRejected]),

    onDropRejected: () => {
      if (props.type === "video") boomRejected("videoType", "");
      else if (props.type === "avatar" || props.type === "cover")
        boomRejected("imageType", "");
      else if (props.type === "media") boomRejected("mediaType", "");
    },
    maxFiles: props.maxFiles,
  });

  const sendFilesToParent = () => {
    props.getFilesFromChild(files);
  };

  useEffect(() => {
    // Make sure to revoke the data uris to avoid memory leaks
    sendFilesToParent();
    //files.forEach(file => URL.revokeObjectURL(file.preview));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [files]);



  return (
    <Upload
      className="Upload"
      noPadding={props.noPadding}
      {...getRootProps({ isDragActive, isDragAccept, isDragReject })}
    >
      <IconSvg Icon={props.iconUpload ? props.iconUpload : "Upload"} />
      <span>{props.text}</span>
      <input {...getInputProps()} />
    </Upload>
  );
}
