import React from "react";
import styled from "styled-components";
import { Card } from "../../helpers/Card";
import { IconSvg } from "../../svg/IconSvg";

const ViewCard = styled(Card)`
  header {
    height: 20rem;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: ${(p) => p.theme.low};

    figure {
      background: ${(p) => p.theme.background};
      border-radius: 50%;
      padding: 3rem;

      svg {
        width: 5rem;
        fill: ${(p) => p.theme.mid};
      }
    }
  }

  picture {
    display: block;
    width: 100%;
    height: ${(p) => (p.imgBehave == "Contain" ? "24rem" : "20rem")};
    padding: ${(p) => (p.imgBehave == "Contain" ? "2rem" : "0")};
    overflow: hidden;
    background: var(--light);

    img {
      object-fit: ${(p) => (p.imgBehave == "Contain" ? "contain" : "cover")};
      width: 100%;
      height: 100%;
    }
  }

  footer {
    padding: var(--normalPads);

    h2,
    h5 {
      text-align: center;
    }
  }
`;

const ViewCardBig = styled.span`
  font-size: 5rem;
  font-family: "fontMedium", sans-serif;
  color: ${(p) =>
    p.headerColor === "Main"
      ? "var(--main)"
      : p.headerColor === "Focus"
      ? "var(--focus)"
      : p.headerColor === "Error"
      ? "var(--error)"
      : p.headerColor === "Success"
      ? "var(--success)"
      : p.headerColor === "Warning"
      ? "var(--warning)"
      : "var(--black)"};
`;

const ViewCardSmallImg = styled.div`
  img {
    object-fit: cover;
    height: 11rem;
    width: 11rem;
    border-radius: 50%;
  }
`;

export const View_Card = (props) => {
  return (
    <ViewCard
      className={props.className} 
      id={props.id}
      imgBehave={props.imgBehave}
      onClick={props.onClick}
    >
      {props.icon || props.header || props.imgSmall ? (
        <header>
          {props.icon ? (
            <figure>
              <IconSvg Icon={props.icon} />
            </figure>
          ) : props.imgSmall ? (
            <ViewCardSmallImg>
              <img src={props.imgSmall} />
            </ViewCardSmallImg>
          ) : (
            <ViewCardBig headerColor={props.headerColor}>
              {props.header}
            </ViewCardBig>
          )}
        </header>
      ) : props.img ? (
        <picture>
          <img src={props.img} onLoad={props.onLoadImg} />
        </picture>
      ) : null}
      {props.title || props.subtitle ? (
        <footer>
          {props.title && <h2>{props.title}</h2>}
          {props.subtitle && <h5>{props.subtitle}</h5>}
          {props.children}
        </footer>
      ) : null}
    </ViewCard>
  );
};
