import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";

const Stat = styled.div`
  display: grid;
  grid-template-columns: 1fr auto;
  grid-gap: 2rem;
  width: 100%;
  background: ${(props) => props.theme.background};
  color: ${(props) => props.theme.color};
  box-shadow: ${(p) => p.theme.in};
  border-radius: var(--smallRadius);
  transition: box-shadow 0.5s;
  overflow: hidden;
  padding: var(--largePads);
`;

const StatLeft = styled.div``;

const StatTitle = styled.h6``;

const StatText = styled.h1``;

const StatRight = styled.div``;

const StatIcon = styled.div`
  width: 5rem;
  height: 5rem;
  padding: 1rem;
  border-radius: 50%;
  background-color: ${(p) => p.theme.low};
  svg {
    width: 100%;
    fill: ${(p) => p.theme.high};
  }
`;

const StatImg = styled.div`
  width: 5rem;
  height: 5rem;
  border-radius: 50%;
  background-color: ${(p) => p.theme.low};
  overflow: hidden;

  img {
    width: 100%;
    object-fit: ${(p) => (p.imgBehave === "Contain" ? "contain" : "cover")};
  }
`;

export const Stat_ = (props) => {
  return (
    <Stat className={props.className + " " + "Stat"}>
      <StatLeft className="StatLeft">
        <StatTitle>{props.title}</StatTitle>
        <StatText>{props.text}</StatText>
        {props.children}
      </StatLeft>
      <StatRight className="StatRight">
        {props.img ? (
          <StatImg>
            <img src={props.img} />
          </StatImg>
        ) : (
          <StatIcon>
            <IconSvg Icon={props.icon} />
          </StatIcon>
        )}
      </StatRight>
    </Stat>
  );
};
