import React from 'react'
import styled from 'styled-components'
import { s3 } from '../../helpers/Links'
import { Grey_, Main_ } from '../button'

const SingleEmpty = styled.div`
    text-align: center;

    h3{
        color: var(--greyDark);
    }

    img{
        max-width: 30rem;
        opacity: .7;
    }
`

const SingleEmptyActions = styled.div`
    display: flex;
    align-items: center;
    justify-content: center;
    gap: 1rem;
    margin-top: 1rem;
`

export const Single_Empty = (props) => {
  return (
    <SingleEmpty>
        {props.title ?
            <h3>{props.title}</h3>
        :
            null
        }
        <img src={s3+"doitforme/morning/app/global/Empty.svg"} />
        {props.text ?
            <p>{props.text}</p>
        :
            null
        }
        {props.main || props.grey ?
            <SingleEmptyActions>
                {props.grey ?
                    <Grey_ text={props.grey} iconLeft={props.iconGrey}/>
                :
                    null
                }
                {props.main ?
                    <Main_ text={props.main} iconLeft={props.iconMain}/>
                :
                    null
                }
            </SingleEmptyActions>
        :
            null    
        }
    </SingleEmpty>
  )
}
