import React from "react";
import styled from "styled-components";
import { Button } from "../../helpers/Button";

const Facebook = styled(Button)`
  background: var(--facebookOne);
  border-radius: var(--normalRadius);
  border: 1px solid var(--facebookOne);

  span {
    color: var(--white);
  }

  &:hover {
    background: var(--facebookTwo);
    border: 1px solid var(--facebookTwo);
  }
`;

export const Facebook_ = (props) => {
  return (
    <Facebook
      onClick={props.onClick}
      id={props.id}
      className={props.className + " " + "Facebook"}
    >
      {props.icon ? (
        <img src="https://genius1071.friktoriaservers.net/doitforme/morning/thirdParty/Facebook.png" />
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
    </Facebook>
  );
};
