import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Input_ } from "./Input_";

const Radio = styled.div`
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: flex-start;
  grid-gap: 1rem;
  user-select: none;
  width: 100%;
  margin-bottom: 1rem;

  &:last-of-type {
    margin-bottom: 0 !important;
  }

  label {
    cursor: pointer;

    &:hover ~ .RadioCircle {
      background: ${(props) => props.theme.low};
    }
  }
`;

const RadioCircle = styled.div`
  position: relative;
  height: 2rem;
  width: 2rem;
  background: ${(props) => props.theme.background};
  box-shadow: ${(props) => props.theme.in};
  border-radius: 50%;
  grid-column-start: 1;
  grid-column-end: 2;
  grid-row-start: 1;
  grid-row-end: 2;

  .RadioCustom {
    position: absolute;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;
    pointer-events: none;
  }

  .Bullet {
    opacity: 0;
    transition: opacity 0.2s ease-in-out;
    position: absolute;
    top: 0.5rem;
    left: 0.5rem;
    height: 1rem;
    width: 1rem;
    border-radius: 50%;
    background: var(--white);
  }

  input {
    opacity: 0;
    z-index: 15;
    position: absolute;
    cursor: pointer;
    top: 0;
    left: 0;
    height: 100%;
    width: 100%;

    &:checked ~ .RadioCustom {
      background: var(--main);
      border-radius: 50%;
      box-shadow: inset 1px 1px 2px var(--mainDark),
        inset -1px -1px 2px var(--mainLight);
    }

    &:checked ~ .Bullet {
      opacity: 1 !important;
    }
  }
`;

export const Radio_ = (props) => {
  return (
    <Radio className={props.className} key={props.key}>
      {props.withInput ? (
        <Input_ placeholder={props.placeholder} />
      ) : (
        <label onClick={props.onClick} for={props.id}>
          <p>{props.text}</p>
        </label>
      )}
      <RadioCircle className="RadioCircle" id={props.id}>
        <input
          value={props.value}
          onChange={props.onChange}
          name={props.name}
          type="radio"
          id={props.id}
          checked={props.checked}
          onClick={props.onClick}
        />
        <span className="RadioCustom"></span>
        <div className="Bullet"></div>
      </RadioCircle>
    </Radio>
  );
};
