import React, { useContext, useState } from "react";
import styled from "styled-components";
import { HamContext, MenuContext } from "../../contexts";
import { LangContext, RegionContext } from "../../contexts/LocalContext";
import {
  Ham,
  HamComboItem,
  HamItem,
  HamMobileItem,
  HamSeparator,
  HamTitle,
} from "../../styles/Ham";
import { IconSvg } from "../../svg/IconSvg";
import { Nav_Theming } from "./Nav_Theming";

const HamTheme = styled.div`
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: var(--normalPads);
`;

export const Nav_Ham_Main = (props) => {
  const { region } = useContext(RegionContext);
  const { setHamState } = useContext(HamContext);
  const { setActiveMenu } = useContext(MenuContext);
  const { language } = useContext(LangContext);

  return (
    <Ham>
      <HamTitle onClick={() => setHamState(false)}>
        <IconSvg Icon="Xicon" />
        <h4>{props.text_Title_Main}</h4>
      </HamTitle>
      <HamTheme>
        <h5>{props.text_Theme_Main}</h5>
        <Nav_Theming />
      </HamTheme>
      {props.role === "Protected" || props.role === "Admin" ? (
        <HamMobileItem>
          <HamSeparator></HamSeparator>
          <HamItem onClick={props.onCLick_Account_Main}>
            <main>
              <picture>
                <img
                  src={props.img_Account_Main}
                  alt={props.imgAlt_Account_Main}
                />
              </picture>
              <h5>{props.text_Account_Main}</h5>
            </main>
          </HamItem>
        </HamMobileItem>
      ) : null}
      {props.role === "Admin" ? (
        <HamItem id={props.idAdminMain} onClick={props.onClick_Admin_Main}>
          <main>
            <picture>
              <IconSvg Icon="User" />
            </picture>
            <h5>{props.text_Admin_Main}</h5>
          </main>
        </HamItem>
      ) : null}
      {props.role === "Protected" || props.role === "Admin" ? (
        <HamItem id={props.idSubscriptionsMain} onClick={props.onClick_Subscriptions_Main}>
          <main>
            <picture>
              <IconSvg Icon="Payment" />
            </picture>
            <h5>{props.text_Subscriptions_Main}</h5>
          </main>
        </HamItem>
      ) : null}
      {props.role === "Protected" || props.role === "Admin" ? (
        <HamItem id={props.idSettingsMain} onClick={props.onClick_Settings_Main}>
          <main>
            <picture>
              <IconSvg Icon="Settings" />
            </picture>
            <h5>{props.text_Settings_Main}</h5>
          </main>
        </HamItem>
      ) : null}
      {props.hamExtraItems}
      <HamItem onClick={() => setActiveMenu("Language")}>
        <main>
          <picture>
            {language === "el" ? (
              <img src="https://genius1071.friktoriaservers.net/doitforme/monica/app/assets/flags/Greek.svg" />
            ) : language === "de" ? (
              <img src="https://genius1071.friktoriaservers.net/doitforme/monica/app/assets/flags/German.svg" />
            ) : (
              <img src="https://genius1071.friktoriaservers.net/doitforme/monica/app/assets/flags/English.svg" />
            )}
          </picture>
          {language === "el" ? (
            <h5>Ελληνικά</h5>
          // ) : language === "de" ? (
          //   <h5>Deutsch</h5>
          ) : (
            <h5>English</h5>
          )}
        </main>
        <aside>
          <IconSvg Icon="Next" />
        </aside>
      </HamItem>
      <HamItem onClick={() => setActiveMenu("Region")}>
        <main>
          <picture>
            <IconSvg Icon="Flag" />
          </picture>
          <h5>{region}</h5>
        </main>
        <aside>
          <IconSvg Icon="Next" />
        </aside>
      </HamItem>
      {props.role === "Protected" || props.role === "Admin" ? (
        <HamComboItem>
          <HamSeparator></HamSeparator>
          <HamItem id={props.idLogout} onClick={props.onClick_Logout}>
            <main>
              <picture>
                <IconSvg Icon="Logout" />
              </picture>
              <h5>{props.text_Logout}</h5>
            </main>
          </HamItem>
        </HamComboItem>
      ) : (
        <HamMobileItem>
          <HamSeparator></HamSeparator>
          <HamItem id={props.idLogin} onClick={props.onClick_Login}>
            <main>
              <picture>
                <IconSvg Icon="Login" />
              </picture>
              <h5>{props.text_Login}</h5>
            </main>
          </HamItem>
        </HamMobileItem>
      )}
    </Ham>
  );
};
