import React from "react";
import styled from "styled-components";
import { device } from "../../helpers/MediaQ";
import { IconSvg } from "../../svg/IconSvg";

const Sidebar = styled.div`
    position: fixed;
    top: 6rem;
    left: 0;
    z-index: 50;
    height: calc(100vh - 6rem);
    border-top: 2px solid ${p => p.theme.low};
    border-right: 2px solid ${p => p.theme.low};
    width: 100%;
    max-width: 30rem;
    background: ${p => p.theme.background};

    @media ${device.sm} {
        max-width: ${p => p.expand ? "30rem" : "8.2rem"};
        padding-top: 4rem;
    }
`

const SidebarExpand = styled.div`
    display: none;

    @media ${device.sm} {
        display: block;
        position: absolute;
        right: 0;
        top: 2px;
        transform: translateX(50%);
        height: 4rem;
        width: 4rem;
        background: ${p => p.theme.low};
        display: flex;
        align-items: center;
        justify-content: center;
        border-radius: 50%;
        border: 2px solid ${p => p.theme.background};
        cursor: pointer;

        svg{
            width: var(--largeIcon);
            fill: ${p => p.theme.color};
            transform: ${p => p.expand ? "rotate(180deg)" : "rotate(0deg)"};
            transition: transform .5s;
        }
    }
`

export const Sidebar_ = (props) => {
  return <Sidebar expand={props.expand}>
      <SidebarExpand expand={props.expand} onClick={props.onExpand} >
        <IconSvg Icon="Next" />
      </SidebarExpand>
    {props.children}
    </Sidebar>;
};
