import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Button } from "../../helpers/Button";

const Focus = styled(Button)`
  background: var(--focus);
  border-radius: var(--normalRadius);
  border: 1px solid var(--focus);

  span {
    color: ${(props) =>
      props.theme === "dark" ? "var(--dark)" : "var(--white)"};
  }

  svg {
    fill: ${(props) =>
      props.theme === "dark" ? "var(--dark)" : "var(--white)"};
  }

  &:hover {
    background: var(--focusLight);
  }
`;

export const Focus_ = (props) => {
  return (
    <Focus
      className={props.className + " " + "Focus"}
      id={props.id}
      size={props.size}
      onClick={props.onClick}
    >
      {props.iconLeft ? (
        <IconSvg Icon={props.iconLeft} />
      ) : props.localIconLeft ? (
        <>{props.localIconLeft}</>
      ) : null}
      {props.text ? <span>{props.text}</span> : null}
      {props.iconRight ? (
        <IconSvg Icon={props.iconRight} />
      ) : props.localIconRight ? (
        <>{props.localIconRight}</>
      ) : null}
    </Focus>
  );
};
