import React, { useContext, useEffect, useState } from "react";
import styled from "styled-components";
import { PhoneContext, RegionContext } from "../../contexts";
import { Dropdown_ } from "./Dropdown_";
import { Input_ } from "./Input_";
import { countries } from "../../json/countries.js";
import _ from "lodash";
import { device } from "../../helpers/MediaQ";

const InputPhoneRegister = styled.div`
  display: grid;
  grid-template-columns: 12rem 1fr;
  align-items: flex-start;
  grid-column-gap: 2rem;

  @media ${device.lg} {
    grid-template-columns: 1fr;
    grid-row-gap: 1rem;
  }

  @media ${device.md} {
    grid-template-columns: auto 1fr;
    grid-row-gap: 0rem;
  }

  @media ${device.sm} {
    grid-template-columns: 1fr;
    grid-row-gap: 1rem;
  }
`;

export const Input_Phone_Register = (props) => {
  const [selected, setSelected] = useState({
    country: "Greece",
    code: "GR",
    phoneCode: "+30",
    flag: "🇬🇷",
  });

  const { region } = useContext(RegionContext);

  const { phoneCode, setPhoneCode } = useContext(PhoneContext);

  const find_region = (region) => {
    let index = countries.findIndex((item) => item.country == region);
    if (index !== -1) {
      let country = countries[index];
      return country;
    }
    return selected;
  };

  useEffect(() => {
    setPhoneCode(find_region(region).phoneCode);
    setSelected(find_region(region));
  }, [region]);

  return (
    <InputPhoneRegister>
      <Dropdown_>
        <select
          value={selected.phoneCode}
          onChange={(e) => {
            const country = countries.find(
              (country) => country.phoneCode === e.target.value
            );
            setSelected(country);
          }}
          className="Dropdown_EmojiAdapt"
        >
          <option value={selected.phoneCode}>
            {selected.flag} {selected.phoneCode}
          </option>
          {countries
            ?.sort((a, b) => a.country.localeCompare(b.country))
            ?.map((item, i) => (
              <option key={i} value={item.phoneCode}>
                {item.flag} {item.country}
              </option>
            ))}
        </select>
      </Dropdown_>
      <Input_
        ref={props.ref}
        value={props.value}
        className={props.className}
        placeholder={props.placeholder}
        id={props.id}
        onChange={props.onChange}
        defaultValue={props.defaultValue}
        onKeyPress={props.onKeyPress}
        onKeyDown={props.onKeyDown}
        disabled={props.disabled}
        required={props.required}
        errors={props.errors}
        helpers={props.helpers}
        successes={props.successes}
        tips={props.tips}
        list={props.list}
        icon_ListItem={props.listIcon}
        defaultListItem={props.defaultListItem}
        onAdd={props.onAdd}
        add={props.add}
        onDelete={props.onDelete}
        onDeleteDefault={props.onDeleteDefault}
      />
    </InputPhoneRegister>
  );
};
