import React, { useState } from 'react'
import styled from 'styled-components'
import { Slider_ } from '../slider/Slider_';
import { Main_Plain } from '../button';
import { IconSvg } from '../../svg/IconSvg';

const StepsHelper = styled.div`
    
    .Slider{

        h3{
            margin-bottom: 0 !important;
        }

        h4{
            font-family: "fontLight", sans-serif !important;
            font-size: 2.3rem !important;
            letter-spacing: 1px !important;
            color: var(--greyDark) !important;
            padding-bottom: .5rem;
            margin-bottom: 2rem;
            margin-top: 4rem;
            border-bottom: 2px solid var(--greyDark);

            &:first-of-type{
                margin-top: 0 !important; 
            }
        }

        h5{
            margin-bottom: 1rem;
        }

        p{
            margin-bottom: 1rem;
        }

        h6{
            margin-bottom: 1rem;
        }

        ul{
            margin-left: 2rem;

            li{
                display: flex;
                align-items: center;
                gap: 1rem;

                svg{
                    width: .7rem;
                    margin-bottom: 1rem;
                    fill: ${p => p.theme.color};
                }
            }
        }

        a{
            color: var(--main);
            cursor: pointer;

            &:hover{
                color: var(--mainLight);
                transition: color .5s;
            }
        }

        img{
            width: 100%;
            border-radius: 1rem;
            overflow: hidden;
        }
    }
`

const StepsHelperForm = styled.div`
    border: 3px dotted ${p => p.theme.background};
    background: ${p => p.theme.mid};
    padding: var(--normalPads);
    border-radius: 1rem;
    display: grid;
    grid-template-columns: auto 1fr;
    grid-gap: 2rem;
`

const StepsHelperRight = styled.div`
    h5{
        color: var(--greyDark);
        margin-bottom: 1rem;
    }

    button{

        svg{
            width: 2rem;
            margin-bottom: 5px;
            fill: var(--warning);
        }
    }
`

const StepsHelperLeft = styled.div`
        width: 3rem;
        fill: var(--warning);
`

export const Steps_Helper = (props) => {

    const [instructions, toggleInstructions] = useState(false);

  return (
    <StepsHelper>
        {instructions ?
            <Slider_ text={props.textSlider} title={props.titleSlider} onClose={() => toggleInstructions(!instructions)} onClick={() => toggleInstructions(!instructions)}>
                {props.children}
            </Slider_>
        :
            null
        }
        <StepsHelperForm>
            {!props.textBtn ?
                <StepsHelperLeft>
                    <IconSvg Icon="Tip" />
                </StepsHelperLeft>
            :
                null
            }
            <StepsHelperRight>
                {props.extras}
                <h5>{props.text}</h5>
                {props.textBtn ?
                    <Main_Plain noPadding iconLeft="Tip" text={props.textBtn} onClick={() => toggleInstructions(!instructions)}/>
                :
                    null
                }
            </StepsHelperRight>
        </StepsHelperForm>
    </StepsHelper>
  )
}
