import React from 'react'
import styled from 'styled-components'

const SubColorCoding = styled.div`
    display: flex;
    align-items: center;
    gap: .5rem;
`

const SubColorCodingBullet = styled.div`
    height: 1rem;
    width: 1rem;
    border-radius: 50%;
    background-color: ${p=> 
        p.subscription === 'lois' ? '#34D355' 
        :p.subscription === 'dailyprofit' ? '#F1F860'
        : '#D54FBA'
    };
`

export const Sub_Color_Coding = (props) => {
  return (
    <SubColorCoding>
        {props.bond ?
            <SubColorCodingBullet subscription='bond' ></SubColorCodingBullet>
        :
            null
        }
        {props.lois ?
            <SubColorCodingBullet subscription='lois' ></SubColorCodingBullet>
        :
            null
        }
        {props.dailyprofit ? 
            <SubColorCodingBullet subscription='dailyprofit' ></SubColorCodingBullet>
        :
            null
        }
    </SubColorCoding>
  )
}
