import React from "react";
import styled from "styled-components";
import { Red_ } from "../button";
import Upload_ from "./Upload_";
import { device } from "../../helpers/MediaQ";
import {
  ValidatorError,
  ValidatorSuccess,
  ValidatorTip,
  ValidatorWarning,
  Validators,
} from "../../helpers/Validator";
import { IconSvg } from "../../svg/IconSvg";

const UploadCover = styled.div`
  background: ${(p) => p.theme.low};
  border-radius: var(--normalRadius);

  h4 {
    margin-bottom: 2rem;
  }
`;

const UploadCoverGrid = styled.div``;

const UploadCoverImage = styled.div`
  width: 100%;
  aspect-ratio: ${(p) => (p.aspect ? p.aspect : "3/1")};
  background: ${(p) => p.theme.bg};
  border-radius: 2rem;
  overflow: hidden;

  img {
    height: 100%;
    width: 100%;
    object-fit: cover;
  }
`;

const UploadCoverActions = styled.div`
  display: flex;
  align-items: center;
  gap: 1rem;
  margin-top: 1rem;
`;

export const Upload_Cover = (props) => {
  return (
    <UploadCover>
      <h4>{props.title}</h4>
      <UploadCoverGrid>
        <UploadCoverImage aspect={props.aspect}>
          {props.img && props.uploaded ? (
            <img src={props.img} />
          ) : (
            <img
              src={
                props.imgDefault
                  ? props.imgDefault
                  : "https://genius1071.friktoriaservers.net/doitforme/morning/app/boiler/DefaultCover.jpg"
              }
            />
          )}
        </UploadCoverImage>
        <UploadCoverActions>
          <Upload_
            maxFiles="1"
            getFilesFromChild={props.getFilesFromChild}
            boomRejected={props.boomRejected}
            accept={props.accept}
            onClick={props.onUpload}
            text={props.upload}
            iconLeft={props.iconUpload ? props.iconUpload : "Upload"}
            maxSize={props.maxSize}
            type={props.type}
            userId={props.userId}
          />
          {props.uploaded || props.hideDelete? (
            <Red_
              onClick={props.onDelete}
              text={props.delete}
              iconLeft={props.iconUpload ? props.iconUpload : "Delete"}
            />
          ) : null}
        </UploadCoverActions>
        {props.errors ? (
          <Validators className="ValidatorErrors">
            {props.errors?.map((error, i) => (
              <ValidatorError key={i}>
                <IconSvg Icon="Error" />
                <h6>{error}</h6>
              </ValidatorError>
            ))}
          </Validators>
        ) : null}
        {props.successes ? (
          <Validators className="ValidatorSuccesses">
            {props.successes?.map((success, i) => (
              <ValidatorSuccess key={i}>
                <IconSvg Icon="Check" />
                <h6>{success}</h6>
              </ValidatorSuccess>
            ))}
          </Validators>
        ) : null}
        {props.helpers ? (
          <Validators className="ValidatorHelpers">
            {props.helpers?.map((helper, i) => (
              <ValidatorWarning key={i}>
                <IconSvg Icon="Warning" />
                <h6>{helper}</h6>
              </ValidatorWarning>
            ))}
          </Validators>
        ) : null}
        {props.tips ? (
          <Validators className="ValidatorTips">
            {props.tips?.map((tip, i) => (
              <ValidatorTip key={i}>
                <IconSvg Icon="Tip" />
                <h6>{tip}</h6>
              </ValidatorTip>
            ))}
          </Validators>
        ) : null}
      </UploadCoverGrid>
    </UploadCover>
  );
};
