import React from "react";
import styled from "styled-components";
import { IconSvg } from "../../svg/IconSvg";
import { Label } from "../../helpers/Input";

const Dropdown = styled.div`
  position: relative;

  select {
    width: 100%;
    cursor: pointer;
    appearance: none;
    outline: 0;
    padding: var(--normalPads);
    font-size: var(--normalText);
    border-radius: var(--smallRadius);
    padding-right: 4rem;
    color: ${(props) => props.theme.color};
    background: ${(props) => props.theme.background};
    border: 1px solid ${(props) => props.theme.background};
    padding-top: 3rem;
    box-shadow: ${props => props.theme.out};
    transition: box-shadow .5s;
  }

  option {
    padding: var(--normalPads);
    font-size: var(--normalText);
  }

  svg {
    position: absolute;
    display: block;
    z-index: 5;
    pointer-events: none;
    fill: ${(props) => props.theme.color};
    height: 0.8rem;
    top: 2.5rem;
    right: 1rem;
  }

  &:hover{
    transition: box-shadow .5s;
    box-shadow: ${props => props.theme.outFocus};
  }
`;

const DropdownLabel = styled(Label)`
  font-size: var(--smallText);
  color: var(--greyDark);
  position: absolute;
  top: 1.8rem;
  left: 1.6rem;
  transform: translateY(-1rem);
  visibility: visible;
  opacity: 1;
  transition-property: opacity, transform;
  transition-duration: 0.5s;
`

export const Dropdown_ = (props) => {
  return (
    <Dropdown>
      {props.label ?
        <DropdownLabel>{props.label}</DropdownLabel>
      :
        null
      }
      <IconSvg Icon="Dropdown" class_Icon="Dropdown_IconAdapt" />
      {props.items ? (
        <select
          className={props.className}
          onChange={props.onChange}
          defaultValue={props.defaultValue}
        >
          {props.items?.map((option, i) => (
            <option value={option.value} key={i}>
              {option.text}
            </option>
          ))}
        </select>
      ) : null}
      {props.children}
    </Dropdown>
  );
};
