import React, { useContext } from 'react'
import styled from 'styled-components'
import { ThemeContext } from '../../contexts'
import { IconSvg } from '../../svg/IconSvg'

const NavTheming = styled.div`
    display: flex;
    align-items: center;
    gap: .5rem;

    picture{
      svg{
        fill: ${p => p.theme.color};
        width: var(--normalIcon);
      }
    }

    section{
        width: 4rem;
        margin-bottom: .2rem;
        height: 1.7rem;
        border-radius: 1rem;
        background: ${p => p.theme.low};
        position: relative;
        cursor: pointer;

        div{
            position: absolute;
            top: .1rem;
            left: .1rem;
            height: 1.5rem;
            width: 1.5rem;
            border-radius: 50%;
            background: var(--main);
            transition: transform .5s;
        }

        .Light{
            transform: translateX(0);
        }

        .Dark{
            transform: translateX(2.3rem);
        }
    }
`

export const Nav_Theming = (props) => {

  const { theme, setTheme } = useContext(ThemeContext)

  return (
    <NavTheming onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')}>
        <picture>
          <IconSvg Icon="Sun"/>
        </picture>
        <section>
            <div className={theme === 'dark' ? 'Dark' : 'Light'}></div>
        </section>
        <picture>
          <IconSvg Icon="Moon"/>
        </picture>
    </NavTheming>
  )
}
