import React, { useEffect, useState } from 'react'
import styled from 'styled-components'
import { breakPoints } from '../../helpers/MediaQ'
import { CardsSixty } from '../../styles/Cards'
import { Card_Loader } from './Card_Loader'

const SixtyCardLoader = styled(CardsSixty)`

`

export const Sixty_Card_Loader = (props) => {

    const [repeats , setRepeats] = useState();
    const ChangeRepeats = (width) => {
        if (width > breakPoints.xl) {
            setRepeats(6);
        }
        else if ( width <= breakPoints.xl && width > breakPoints.md) {
            setRepeats(4);
        }
        else if ( width <= breakPoints.md && width > breakPoints.sm) {
            setRepeats(6);
        }
        else if (width <= breakPoints.sm && width > breakPoints.xs) {
            setRepeats(4);
        } else if (width < breakPoints.xs){
            setRepeats(2);
        }
    } 

    window.addEventListener('resize', () => 
        {
            let width = window.innerWidth
            ChangeRepeats(width)
        }
    )

    useEffect(() => {
        let width = window.innerWidth;
        ChangeRepeats(width);
    }, []);

  return (
    <SixtyCardLoader>
        {[...Array(repeats)].map((i) =>
            <Card_Loader key={i} children={props.children} circle={props.circle}/>
        )}
    </SixtyCardLoader>
  )
}
