import React, { useState } from "react";
import styled, { keyframes } from "styled-components";
import { Card } from "../../helpers/Card";
import { IconSvg } from "../../svg/IconSvg";
import { device } from "../../helpers/MediaQ";
import { Grey_Link, Main_Plain, Red_ } from "../button";

const revealActions = keyframes`
   from {
      transform: translateX(0rem);
    }
    to {
      transform: translateX(-15rem);
    }
`;

const hideActions = keyframes`
   from {
      transform: translateX(-15rem);
    }
    to {
      transform: translateX(0rem);
    }
`;

const OnClickCard = styled.div`
  position: relative;
  border-radius: var(--smallRadius);
`;

const OnClickOptions = styled.div`
  background: ${(p) => p.theme.low};
  height: 100%;
  width: 100%;
  border-radius: var(--smallRadius);
  position: absolute;
  top: 0;
  left: 0;
  display: flex;
  justify-content: flex-end;
`;

const OnClickOptionsActions = styled.div`
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2rem;
  padding: 1.5rem;
`;

const OnClickBody = styled(Card)`
  cursor: pointer;
  height: 100%;
  animation: ${(p) => (p.isOptions ? revealActions : hideActions)} 0.5s forwards;
  background: ${(p) => p.theme.background};
  transition: transform 0.5s;

  &:hover {
    box-shadow: ${(p) => p.theme.outFocus};
    transition: box-shadow 0.5s;
  }

  header {
    height: 20rem;
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: center;
    background: ${(p) => p.theme.low};

    figure {
      background: ${(p) => p.theme.background};
      border-radius: 50%;
      padding: 3rem;

      svg {
        width: 5rem;
        fill: ${(p) => p.theme.mid};
      }
    }
  }

  picture {
    display: block;
    width: 100%;
    height: ${(p) => (p.imgBehave == "Contain" ? "24rem" : "20rem")};
    padding: ${(p) => (p.imgBehave == "Contain" ? "2rem" : "0")};
    overflow: hidden;
    background: ${(p) => p.theme.background};

    img {
      object-fit: ${(p) => (p.imgBehave == "Contain" ? "contain" : "cover")};
      width: 100%;
      height: 100%;
    }
  }
`;

const OnClickBig = styled.span`
  font-size: 5rem;
  font-family: "fontMedium", sans-serif;
  color: ${(p) =>
    p.headerColor === "Main"
      ? "var(--main)"
      : p.headerColor === "Focus"
      ? "var(--focus)"
      : p.headerColor === "Error"
      ? "var(--error)"
      : p.headerColor === "Success"
      ? "var(--success)"
      : p.headerColor === "Warning"
      ? "var(--warning)"
      : "var(--black)"};
`;

const OnClickSmallImg = styled.div`
  img {
    object-fit: cover;
    height: 11rem;
    width: 11rem;
    border-radius: 50%;
  }
`;

const OnClickCardBottom = styled.div`
  padding: var(--normalPads);

  h3,
  h5 {
    text-align: center;
    white-space: nowrap;
    width: calc(100%);
    overflow: hidden;
  }
`;

const OnClickCardTitle = styled.div`
  h3,
  h5 {
    text-align: center;
  }
`;

const OnClickCardFix = styled.div`
  position: relative;
`;

const OnClickCardFixText = styled.h6`
  position: absolute;
  top: 50%;
  left: 50%;
  height: 3rem;
  width: 100%;
  transform: translate(-50%, -50%);
  z-index: 2;
  padding: 0.5rem 1rem;
  background: ${(p) => p.theme.low};
  border-radius: var(--smallRadius);
  text-align: center;

  @media ${device.sm} {
    display: none;
  }
`;

const OnClickCardChildren = styled.div`
  padding: var(--normalPads);
  margin-top: 1rem;
`;

export const On_Click_Card = (props) => {
  const maxTitle = 16;
  const maxSubtitle = 30;
  const [nameIsHovered, setNameIsHovered] = useState(false);

  return (
    <OnClickCard
      href={props.href}
      className={props.className}
      imgBehave={props.imgBehave}
      key={props.key}
    >
      {props.options ? (
        <OnClickOptions>
          <OnClickOptionsActions>
            {props.onView && (
              <Main_Plain
                iconRight= {props.iconView ? props.iconView : "EyeOpen"}
                noPadding
                text={props.view}
                onClick={props.onView}
              />
            )}
            {props.onEdit && (
              <Main_Plain
              iconRight= {props.iconEdit ? props.iconEdit : "Edit"}
                text={props.edit}
                noPadding
                onClick={props.onEdit}
              />
            )}
            {props.extraOptions}
            {props.onDelete && (
              <Red_
                iconRight="Delete"
                text={props.delete}
                noPadding
                onClick={props.onDelete}
              />
            )}
            {props.optionsChildren}
          </OnClickOptionsActions>
        </OnClickOptions>
      ) : null}
      <OnClickBody className={props.className + " " + 'OnClickBody'} id={props.id}
        imgBehave={props.imgBehave}
        onClick={props.onClick}
        isOptions={props.isOptions}
      >
        {props.icon || props.header || props.imgSmall ? (
          <header>
            {props.icon ? (
              <figure>
                <IconSvg Icon={props.icon} />
              </figure>
            ) : props.imgSmall ? (
              <OnClickSmallImg>
                <img src={props.imgSmall} />
              </OnClickSmallImg>
            ) : (
              <OnClickBig headerColor={props.headerColor}>
                {props.header}
              </OnClickBig>
            )}
          </header>
        ) : props.img ? (
          <picture>
            <img src={props.img} onLoad={props.onLoadImg} />
          </picture>
        ) : null}
        {props.title || props.subtitle ? (
          <OnClickCardBottom
            onMouseEnter={() => setNameIsHovered(true)}
            onMouseLeave={() => setNameIsHovered(false)}
          >
            {props.title && (
              <OnClickCardTitle>
                {props.title?.length <= maxTitle ? (
                  <h3>{props.title}</h3>
                ) : (
                  <OnClickCardFix>
                    <h3>{props.title.substring(0, maxTitle) + "..."}</h3>
                    {nameIsHovered && (
                      <OnClickCardFixText>{props.title}</OnClickCardFixText>
                    )}
                  </OnClickCardFix>
                )}
              </OnClickCardTitle>
            )}
            {props.subtitle && (
              <OnClickCardTitle>
                {props.subtitle?.length <= maxSubtitle ? (
                  <h5>{props.subtitle}</h5>
                ) : (
                  <OnClickCardFix>
                    <h5>{props.subtitle.substring(0, maxSubtitle) + "..."}</h5>
                    {nameIsHovered && (
                      <OnClickCardFixText>{props.subtitle}</OnClickCardFixText>
                    )}
                  </OnClickCardFix>
                )}
              </OnClickCardTitle>
            )}
          </OnClickCardBottom>
        ) : null}
        {props.children ? (
          <OnClickCardChildren className="Children">{props.children}</OnClickCardChildren>
        ) : null}
      </OnClickBody>
    </OnClickCard>
  );
};
